input.command:
WAVE_WORKTREE_MANIFEST="/private/tmp/claude-501/-Users-myankelev-Code-random-cipher-box/861dbcb7-8d4e-4ad5-840b-8fe8eebad3b0/scratchpad/gsd-worktree-wave3.json"
[ -f "$WAVE_WORKTREE_MANIFEST" ] || { echo "BLOCKED: missing manifest"; exit 1; }
# Pin to orchestrator root from manifest (#3174, #630)
PRIMARY_WT=$(MANIFEST="$WAVE_WORKTREE_MANIFEST" node -e 'const fs=require("fs");try{const j=JSON.parse(fs.readFileSync(process.env.MANIFEST,"utf8"));if(j&&j.orchestrator_root)process.stdout.write(String(j.orchestrator_root))}catch(e){}')
[ -n "$PRIMARY_WT" ] || { echo "FATAL: no orchestrator root"; exit 1; }
cd "$PRIMARY_WT" || exit 1
ORCH_BRANCH=$(git rev-parse --abbrev-ref HEAD)
[ "$ORCH_BRANCH" = "feat/web-client-runtime-integration" ] || { echo "FATAL: on '$ORCH_BRANCH', expected feat/web-client-runtime-integration"; exit 1; }
node .claude/gsd-core/bin/gsd-tools.cjs query worktree.cleanup-wave --manifest "$WAVE_WORKTREE_MANIFEST" || exit 1

